/* Minimal osconfig.h shim.
 *
 * In a real cFS build this file is GENERATED by CMake from sample_defs/default_osconfig.cmake.
 * There is nothing to copy, which is itself the finding: no cFE source compiles without a mission
 * configuration. This hand-written stand-in carries only what the headers on the path to
 * cfe_msg_ccsdspri.c actually reference, so the translation work can start before the build
 * system is ported. */
#ifndef OSCONFIG_H
#define OSCONFIG_H
#define OS_MAX_API_NAME        20
#define OS_MAX_FILE_NAME       20
#define OS_MAX_PATH_LEN        64
#define OS_MAX_LOCAL_PATH_LEN  (OS_MAX_PATH_LEN + OS_MAX_FILE_NAME)
#define OS_MAX_SYM_LEN         64
#define OS_MAX_TASKS           64
#define OS_MAX_QUEUES          64
#define OS_MAX_COUNT_SEMAPHORES 20
#define OS_MAX_BIN_SEMAPHORES  20
#define OS_MAX_MUTEXES         20
#define OS_MAX_CONDVARS        20
#define OS_MAX_MODULES         20
#define OS_MAX_TIMERS          5
#define OS_MAX_TIMEBASES       5
#define OS_MAX_NUM_OPEN_FILES  50
#define OS_MAX_NUM_OPEN_DIRS   4
#define OS_MAX_FILE_SYS        14
#define OS_MAX_CONSOLES        1
#define OS_MAX_CPUS            1
#define OS_BUFFER_SIZE         172
#define OS_BUFFER_MSG_DEPTH    100
#define OS_UTILITY_TASK_ON     0
#define OS_FS_DEV_NAME_LEN     32
#define OS_FS_PHYS_NAME_LEN    64
#define OS_FS_VOL_NAME_LEN     32
#endif
